end
uo.met=yo
local Io=oo:FindFirstChild(SJe[2662])
local Jo={}
for Ko,Lo in ipairs(Io and Io:GetChildren()or{})do
local Mo=(Lo:IsA(SJe[2663])and tonumber(Lo.Value))or 1
if Mo~=0 then
Jo[Lo.Name]=Mo
end
end
for No,Oo in pairs(Jo)do
local Po=gn.foeBuffs[No]
if not Po then
Po={first=kn,last=kn,n=0,foes=0,near=0,boss=0,max=Oo,durs={},sp=0,spN=0,onsets={}}
gn.foeBuffs[No]=Po
end
Po.n,Po.last,Po.max=Po.n+1,kn,math.max(Po.max,Oo)
if po then
Po.near=Po.near+1
end
if uo.boss then
Po.boss=Po.boss+1
end
if not uo.on[No]then
uo.on[No]=kn
Po.foes=Po.foes+1
if#Po.onsets<200 then
table.insert(Po.onsets,kn)
end
end
if vo and(uo.speed0 or 0)>0 then
Po.sp,Po.spN=Po.sp+vo.WalkSpeed/uo.speed0,Po.spN+1
end
end
for Qo,Ro in pairs(uo.on)do
if not Jo[Qo]then
local So=gn.foeBuffs[Qo]
if So and#So.durs<80 then
table.insert(So.durs,kn-Ro)
end
uo.on[Qo]=nil
end
end
end
uo.hp=mo.hp
uo.frac=(mo.hp or 0)/wo
end
end
end
for To,Uo in pairs(gn.foe)do
if not io[To]then
if#gn.deaths<600 and Uo.frac then
