end
return{seen=true,buff=xq,nums={maxSeen=yq.max,steps= #yq.vals,transformTo=Bq},why=string.format(SJe[2690],xq,tostring(yq.max))}
end
if ep.family==SJe[2457]then
local Lq,Mq,Nq={},{},nil
