return true
end
return dD.kind==SJe[2730]and tostring(dD.level):find(SJe[2794],1,true)~=nil
end
function mb.charms()
local eD=N.prof()
local fD={}
for gD,hD in pairs((eD and eD.inventory and eD.inventory.unique_items)or{})do
local iD=type(hD)==SJe[2259]and N.Items[hD.item_id]
if type(iD)==SJe[2259]and iD.item_group==SJe[2795]then
local jD={uuid=hD.uuid or gD,id=hD.item_id,tier=tonumber(iD.tier)or 0,rolls={}}
local kD=type(hD._unique_item_data)==SJe[2259]and hD._unique_item_data._unique_charm_data
jD.worn=type(kD)==SJe[2259]and kD._e~=nil
local lD=type(kD)==SJe[2259]and kD._d
for mD,nD in pairs(type(lD)==SJe[2259]and lD or{})do
if type(nD)==SJe[2259]and nD._t then
jD.rolls[tostring(nD._t)]=(jD.rolls[tostring(nD._t)]or 0)+(tonumber(nD._d)or 0)
end
end
table.insert(fD,jD)
end
end
return fD
end
function mb.charmOn()
