function mb.charmScore(sD,tD)
local uD=(tD and tonumber(tD.p))or 0.5
local vD,wD,xD=sD.rolls.unit_damage or 0,sD.rolls.reward_mul or 0,0
for yD,zD in pairs(sD.rolls)do
if yD~=SJe[2796]and yD~=SJe[2797]then
xD=xD+zD
end
end
if uD>=0.92 or(O.huntPearls and tD and tD.kind==SJe[2282]and mb.is(tD.level)and uD>=0.5)then
return wD*3+vD+xD*0.5
end
return vD*3+wD+xD*0.5
end
