if mb.charmOn()==TD.uuid then
P.charm.uuid,P.charm.at,P.charm.failAt=TD.uuid,os.time(),nil
F.saveSoon()
F.log(1,SJe[2807],string.format(SJe[2808],mb.charmWords(TD),tostring(SD.label),math.floor((tonumber(SD.p)or 0)*100+0.5),(tonumber(SD.p)or 0)>=0.92 and SJe[2799]or SJe[2709]))
else
