function mb.weatherStrength(BE)
local CE=mb.fx(BE)
local DE=CE.dmg/CE.cd/CE.hp/CE.speed*(1+(CE.range-1)/2)
for EE,FE in pairs(CE.kinds)do
DE=DE*(1+bb.rogueShare(EE)*FE)
end
if CE.ice>0 then
local GE=bb.rogueShare(SJe[2410])
DE=DE*(GE+(1-GE)/(1-CE.ice+CE.ice/gb.modFactor(SJe[2818])))
end
if CE.fly>0 then
DE=DE*(1-CE.fly*0.5)
end
if CE.noCC then
DE=DE*0.95
end
if CE.shroud then
DE=DE*0.9
end
if CE.zap then
DE=DE*0.85
end
return DE/mb.weatherK(BE)
end
mb.WEATHER_K_MIN,mb.WEATHER_K_MAX,mb.WEATHER_K_RUNS=0.5,4,10
function mb.weatherK(HE)
local IE=HE and type(P.hunt)==SJe[2259]and type(P.hunt.wk)==SJe[2259]and P.hunt.wk[tostring(HE)]or nil
return type(IE)==SJe[2259]and tonumber(IE.k)or 1
end
function mb.weatherLearn()
if bb.withOthers or#game:GetService(SJe[1157]):GetPlayers()>1 then
return
end
local JE=bb.huntWeather or mb.weatherNow()
local KE,LE=bb.pred,bb.calRun
if not JE or type(KE)~=SJe[2259]or type(LE)~=SJe[2259]then
return
end
local function ME(NE,OE)
return type(NE)==SJe[2259]and tonumber(NE[OE]or NE[tostring(OE)])or nil
end
local PE={}
for QE=2,bb.wave()do
local RE,SE=ME(LE.alive,QE),ME(KE.aliveAt,QE)
if RE and SE and RE>0 and SE>0 then
table.insert(PE,RE/SE)
end
end
if#PE<3 then
return
end
table.sort(PE)
local TE=PE[math.ceil(#PE/2)]
P.hunt.wk=type(P.hunt.wk)==SJe[2259]and P.hunt.wk or{}
local UE=P.hunt.wk[tostring(JE)]
local VE=math.min(mb.WEATHER_K_RUNS-1,type(UE)==SJe[2259]and tonumber(UE.n)or 0)
local WE=mb.weatherK(JE)
local XE=math.max(1,VE)
local YE=math.exp((XE*math.log(WE)+math.log(WE*TE))/(XE+1))
YE=U.clamp(YE,mb.WEATHER_K_MIN,mb.WEATHER_K_MAX)
bb.wkWas={w=tostring(JE),old=UE}
P.hunt.wk[tostring(JE)]={k=YE,n=(type(UE)==SJe[2259]and tonumber(UE.n)or 0)+1,at=os.time()}
F.log(1,SJe[2819],string.format(SJe[2820],tostring(JE),TE,tostring(JE),YE,WE,P.hunt.wk[tostring(JE)].n))
end
function mb.cardGems(ZE,_E)
