aF=aF+math.abs(eF)*bF*O.pearlValue
elseif dF.type==SJe[2822]then
local fF,gF=pcall(W.rewardValue,dF.reward)
if fF then
aF=aF+(tonumber(gF)or 0)
end
elseif dF.type==SJe[2823]then
aF=aF+eF*mb.STARFALL_GEMS
elseif dF.type==SJe[2824]then
aF=aF+eF*100
