if hF and ZE.weather==SJe[2760]then
aF=aF+mb.starfallRemnants(50-(tonumber(_E)or 0))*W.remnantGems(SJe[2764])
end
local iF=mb.board()
if hF and iF and ZE.weather~=SJe[2766]and not iF.weathers[ZE.weather]then
aF=aF+(1000+5000*O.pearlValue+50*W.remnantGems(SJe[2764]))/mb.WEATHERS
end
end
return aF
end
