end
end
if yG then
break
end
end
if not yG then
break
end
end
if#kG==0 then
return nil
end
return jG,string.format(SJe[2847],table.concat(kG,SJe[2383]),math.floor(mb.teamDrop(jG,MF)*100+0.5),math.floor(lG*100+0.5),UF)
