function W.icWinP(oR)
local pR=oR.rec or W.rec(oR.key)
local qR=W.icLost(oR.room)
local rR=qR and qR.n or 0
local sR=((tonumber(pR.wins)or 0)+(oR.p0 or W.PRIOR_WIN.castle)*2)/((tonumber(pR.runs)or 0)+2)
local tR=W.sim(oR)
local uR,vR=0,0
if tR and tonumber(tR.p)then
local wR=type(tR.trust)==SJe[2259]and tR.trust or nil
local xR=wR~=nil and not wR.ok
local yR=xR and(tonumber(wR.ratio)or 1)>1
if not xR or(yR and not tR.won)or(xR and not yR and tR.won)then
local zR,AR=pcall(gb.styleP,tR)
uR,vR=(zR and tonumber(AR))or tonumber(tR.p),W.IC.SIM_W
end
end
return(sR*2+uR*vR)/(rR+2+vR)
end
function W.winP(BR)
if BR.kind==SJe[2728]then
return W.icWinP(BR)
end
if BR.kind==SJe[2726]and O.dailyMatch and not O.dailyLoop then
local CR,DR=pcall(W.needsHelp,BR)
if CR and DR then
return W.MATCHED_DAILY_P
end
end
local ER=BR.rec
local FR=BR.p0 or W.PRIOR_WIN[BR.kind]or 0.7
local GR=W.sim(BR)
if GR and not(GR.trust and not GR.trust.ok)then
local HR=GR.calibrated or ER.runs>0
local IR=(GR.trust and GR.trust.ok)and 6 or(HR and 3 or 1.5)
local JR=(HR or GR.hopeless)and 0 or 2
local KR,LR=pcall(gb.styleP,GR)
return(ER.wins+FR*JR+(KR and LR or GR.p)*IR)/(ER.runs+JR+IR)
end
return(ER.wins+FR*2)/(ER.runs+2)
end
