function kb.gainXp(qeb,reb)
local seb,teb=tonumber(qeb.xp)or 0,kb.xpFor(qeb.unit_id,kb.cap(qeb))
local ueb=math.max(0,teb-seb)
if ueb<=0 or(reb or 0)<=0 then
return 0,0
end
local veb=math.min(reb,ueb)
local web=kb.base(qeb)
if web<=0 then
return 0,veb
end
return kb.share(qeb.unit_id)*(kb.score(kb.whatIf(qeb,{xp=seb+veb}))/web-1)*100,veb
end
