function kb.relicWorth(xeb,yeb)
local zeb=yeb._unique_item_data and yeb._unique_item_data._unique_relic_data
if not zeb then
return 0
end
local Aeb=N.Items[yeb.item_id]or{}
local Beb,Ceb=V.types(xeb.unit_id)
if Aeb.main_damage_type and Aeb.main_damage_type~=SJe[2962]and Aeb.main_damage_type~=Ceb then
return 0
end
local Deb,Eeb=0,0
for Feb,Geb in pairs(zeb._core_damage_type_buffs or{})do
if Beb[Geb.damage_type]then
Deb=Deb+(tonumber(Geb.mul)or 0)+(tonumber(Geb.add_upg)or 0)*0.01+(tonumber(Geb.pen)or 0)*0.001
Eeb=Eeb+(tonumber(Geb.crit)or 0)
end
end
Deb=Deb+Eeb*0.5
local Heb=V.rows(xeb.unit_id)
local Ieb=Heb and Heb[Heb.max]
local Jeb=(Ieb and tonumber(Ieb.cd)or 0)*V.mult(xeb,SJe[2710])
for Keb,Leb in pairs(zeb._unique_relic_effects or{})do
local Meb=type(Leb.params)==SJe[2259]and Leb.params or{}
if Leb.id==SJe[3363]then
local Neb=math.min(1,(tonumber(Meb.extra_damage)or 0)*Jeb/math.max(1,tonumber(Meb.time_interval)or 40))
local Oeb=V.DRONES and V.DRONES[xeb.unit_id]
if Oeb and Oeb.late and Jeb>0 then
local Peb=1/Jeb
Neb=Neb*Peb/(Peb+(tonumber(Oeb.max)or 0)*(tonumber(Oeb.late.dmg)or 0)*(tonumber(Oeb.hits)or 1)/math.max(0.1,tonumber(Oeb.late.cd)or 4))
end
Deb=Deb+Neb
elseif Leb.id==SJe[3364]then
Deb=Deb+(tonumber(Meb.dmg_buff)or 0)*0.25
elseif Leb.id==SJe[3365]then
Deb=Deb+(tonumber(Meb.dmg_buff)or 0)*Eeb
elseif Leb.id==SJe[3366]then
if Beb.magic then
Deb=0
else
Deb=Deb+(tonumber(Meb.dmg_buff)or 0)*0.3
end
elseif Leb.id==SJe[3367]then
if Beb.water_damage then
Deb=Deb+0.05
end
elseif Leb.id==SJe[2411]then
local Qeb=tonumber(Meb.duration_buff)or tonumber(type(Leb.static_params)==SJe[2259]and Leb.static_params.duration_buff)or 2
local Reb,Seb=pcall(V.attackInfo,Ieb and Ieb.atk,Ieb and Ieb.range)
local Teb,Ueb=Reb and tonumber(Seb.burn)or 0,Reb and tonumber(Seb.dot)or 0
if Teb<=0 then
local Veb,Web=pcall(pb.model,xeb.unit_id,Reb and Seb or nil,Ieb)
if Veb and type(Web)==SJe[2259]and(tonumber(Web.burnDot)or 0)>0 then
Teb,Ueb=Web.burnDot,Ueb+(tonumber(Web.dot)or 0)
end
end
Deb=Deb+Teb*math.max(0,Qeb-1)/(1+Ueb)
end
end
return Deb
end
function kb.relicPlan()
