if shb>0 then
nhb=math.max(nhb,rhb/shb)
end
end
end
local thb=nhb*(O.strengthValue or 300)
if(tonumber(N.cur(SJe[2334]))or 0)>(O.xpGoldFloor or 100000)then
thb=math.min(thb,(N.GOLD_VALUE or 0.02)/14)
end
return thb
