function kb.xpGuess(uhb)
local vhb=uhb.level and N.Levels[uhb.level]
if not vhb then
return 0
end
local whb=math.min(9,tonumber(vhb.story_world_rank)or tonumber(uhb.rank)or 9)
local xhb=tonumber(vhb.story_level_rank)or 6
local yhb=(uhb.kind==SJe[2308]and 1.5 or 1)*(whb>5 and 2 or 1)
local zhb=2.1564^(whb-1)*(40+10*xhb)/yhb
if uhb.kind==SJe[2284]then
zhb=3*30*2.1564^(whb-1)/yhb
end
local Ahb=whb>=9 and 0.3 or(whb>=7 and 0.5 or 1)
return zhb*Ahb*6
end
function kb.modeBonus(Bhb)
if not(O.team and O.teamXp)or Bhb.kind==SJe[2285]or Bhb.kind==SJe[2282]then
return 0
end
local Chb=kb._xpRate and os.time()-(kb._xpRateAt or 0)<300 and kb._xpRate or nil
if not Chb then
Chb=kb.xpRate()
kb._xpRate,kb._xpRateAt=Chb,os.time()
end
if Chb<=0 then
return 0
end
local Dhb=P.modes and P.modes[Bhb.key]
local Ehb=tonumber(Dhb and Dhb.xp)or kb.xpGuess(Bhb)
local Fhb=Ehb*Chb
if Fhb<1 then
return 0
end
return Fhb,string.format(SJe[3384],U.fmt(Ehb),math.floor(Fhb+0.5))
end
function kb.xpSettle()
