function kb.feedPlan(Phb)
local Qhb=V.trait(Phb)
local Rhb=Qhb==SJe[3386]and 1.5 or 1
local Shb=math.max(0,kb.xpFor(Phb.unit_id,kb.cap(Phb))-(tonumber(Phb.xp)or 0))
local Thb,Uhb,Vhb={},0,0
for Whb,Xhb in ipairs(kb.foodHeld())do
local Yhb=Xhb.xp*Rhb
local Zhb=math.min(Xhb.n,math.floor((Shb-Uhb)/math.max(1,Yhb)))
if Zhb>0 then
Thb[Xhb.id]=Zhb
Uhb=Uhb+Zhb*Yhb
Vhb=Vhb+Zhb
end
end
return{feed=Thb,planned=Uhb,n=Vhb}
end
function kb.run(aib)
