cb.add(string.format(SJe[3389],gib,aib.name),gib,SJe[3390],string.format(SJe[3391],U.fmt(nib),pib))
kb.note(string.format(SJe[3392],aib.name,gib,U.fmt(nib),pib,math.abs(nib-fib)>fib*0.1 and string.format(SJe[3393],U.fmt(fib))or SJe[1178]))
