end
table.insert(mDb,string.format(SJe[3895],V.name((N.session().collection:get_unit_by_uuid(sDb)or{}).unit_id or SJe[2510]),tDb and(SJe[3896]..tDb)or SJe[1178],tostring(yDb),tostring(zDb)))
task.wait(0.8)
end
end
