end
aDb={}
for BDb,CDb in ipairs(V.equipped())do
aDb[CDb.uuid]=true
end
end
W._sigAt=nil
if lDb then
F.log(1,SJe[3397],SJe[3897].. #ZCb..SJe[3898]..tostring(_Cb))
else
local DDb={}
for EDb,FDb in ipairs(V.equipped())do
table.insert(DDb,V.name(FDb.id))
end
F.log(1,SJe[3397],SJe[3899]..tostring(_Cb)..SJe[3900]..table.concat(DDb,SJe[2383])..SJe[3901]..table.concat(mDb,SJe[2650]))
if not ab.refilling and#V.equipped()<6 then
ab.refilling=true
local GDb,HDb={},{}
for IDb,JDb in ipairs(V.equipped())do
HDb[JDb.uuid]=true
end
for KDb,LDb in ipairs(P.savedTeam or{})do
if not HDb[LDb]and N.session().collection:get_unit_by_uuid(LDb)then
table.insert(GDb,LDb)
end
end
local MDb=0
for NDb,ODb in ipairs(GDb)do
if#V.equipped()>=6 then
break
end
F.request(SJe[3395],SJe[3396],ODb)
task.wait(0.8)
local PDb=U.now()
while U.now()-PDb<3 and#V.equipped()<math.min(6,MDb+1+(6- #GDb))do
task.wait(0.25)
end
for QDb,RDb in ipairs(V.equipped())do
if RDb.uuid==ODb then
MDb=MDb+1
end
end
end
local SDb={}
for TDb,UDb in ipairs(V.equipped())do
table.insert(SDb,V.name(UDb.id))
end
F.log(1,SJe[3397],string.format(SJe[3902],MDb,table.concat(SDb,SJe[2383])))
W._sigAt=nil
ab.refilling=nil
end
end
F.saveSoon()
return lDb
end
