function eb.upgradeGain(qKb,rKb,sKb,tKb,uKb,vKb)
local wKb,xKb=rKb[sKb],rKb[sKb+1]
local yKb=(wKb.cd>0 and wKb.damage/wKb.cd or 0)
local zKb=(xKb.cd>0 and xKb.damage/xKb.cd or 0)*V.aoe(xKb.atk,xKb.range)/math.max(0.3,V.aoe(wKb.atk,wKb.range))
local AKb=yKb>0 and qKb*(zKb/yKb-1)or(vKb or 0)
local BKb=rKb[sKb+2]
if BKb and sKb+1<rKb.max and BKb.cd>0 and xKb.cd>0 and yKb>0 then
local CKb=qKb*((BKb.damage/BKb.cd)/yKb-1)
local DKb=tKb+BKb.cost*uKb
if CKb/DKb>AKb/tKb then
AKb=AKb+(CKb/DKb*tKb-AKb)*0.5
end
end
local EKb=(xKb.range or 0)>(wKb.range or 0)and(1+((xKb.range-wKb.range)/math.max(1,wKb.range)))or 1
return math.max(0,AKb)*EKb
end
function eb.dpsFor(FKb,GKb)
if GKb<=0 then
return 0
end
local HKb={}
for IKb,JKb in ipairs(FKb)do
if not JKb.farm and not JKb.grif and JKb.gain>0 then
table.insert(HKb,JKb)
end
end
table.sort(HKb,function(KKb,LKb)
return KKb.gain/KKb.cost>LKb.gain/LKb.cost
end)
local MKb,NKb=0,0
for OKb,PKb in ipairs(HKb)do
if GKb<=0 then
break
end
NKb=PKb.gain/PKb.cost
local QKb=math.min(1,GKb/PKb.cost)
MKb=MKb+PKb.gain*QKb
GKb=GKb-PKb.cost*QKb
end
return MKb+math.max(0,GKb)*NKb*0.7
end
function eb.shieldDps(RKb,SKb,TKb,UKb,VKb,WKb,XKb)
if(UKb or 0)<=0 or(RKb or 0)<=0 or(VKb or 0)<=0 then
return RKb or 0
end
SKb,TKb,WKb=math.max(0.3,SKb or 2),math.max(1,TKb or 1),WKb or 1
local YKb=RKb*WKb*SKb/TKb
return VKb*TKb/((UKb/math.max(1,XKb or 1)+math.max(1,VKb/YKb))*SKb)/WKb
end
function eb.shieldGain(ZKb,_Kb,aLb,bLb,cLb,dLb,eLb,fLb)
local gLb,hLb=V.attackInfo(_Kb.atk,_Kb.range),V.attackInfo(bLb.atk,bLb.range)
local iLb=eb.shieldDps(ZKb,(tonumber(_Kb.cd)or 2)*(eLb or 1),gLb.n,cLb,dLb,fLb,gLb.hits)
local jLb=eb.shieldDps(aLb,(tonumber(bLb.cd)or 2)*(eLb or 1),hLb.n,cLb,dLb,fLb,hLb.hits)
local kLb=math.max(0,((tonumber(bLb.range)or 0)-(tonumber(_Kb.range)or 0))/math.max(1,tonumber(_Kb.range)or 1))
return math.max(0,jLb-iLb)+iLb*kLb
end
function eb.shieldWork(lLb,mLb,nLb,oLb,pLb,qLb,rLb,sLb,tLb)
if(oLb or 0)<=0 then
return 0
end
local uLb=3*oLb*(pLb or 1)/math.max(1,qLb or 20)
if(nLb or 0)>=uLb then
return 0
end
return math.max(1,lLb or 1)*math.max(1,tLb or 1)/math.max(0.3,mLb or 2)*math.min(rLb or 0,sLb or 0)
end
function eb.holdGain(vLb,wLb,xLb,yLb)
if not vLb or(wLb or 0)<=0 then
return 0
end
local zLb,ALb=tonumber(vLb.stun)or 0,tonumber(vLb.slowTime)or 0
if zLb<=0 and ALb<=0 then
return 0
end
local BLb,CLb=zLb>0 and zLb or ALb,zLb>0 and 1 or(tonumber(vLb.slowPct)or 0.3)
local DLb=CLb*BLb/(BLb+(tonumber(vLb.ccCd)or 8))
local ELb=DLb/math.max(0.1,1-DLb)
return wLb*ELb*U.clamp(xLb or 0.5,0,1)*math.min(1,(tonumber(vLb.n)or 1)/2)/(1+(yLb or 0))
end
function eb.bleedGain(FLb,GLb,HLb,ILb)
if(FLb or 0)<=0 then
return 0
end
local JLb=GLb or 0
for KLb,LLb in ipairs(HLb or{})do
JLb=math.max(JLb,(tonumber(LLb.hp)or 0)*0.5)
end
return FLb*JLb*(ILb and 0.5 or 1)
end
function eb.bleedShare(MLb,NLb,OLb,PLb)
if MLb<=0 or not NLb then
return 0
end
if PLb then
return NLb==0 and MLb or MLb/(NLb+1)
end
return OLb<NLb and MLb/(NLb-OLb)or 0
end
function eb.keepsUp(QLb,RLb,SLb,TLb,ULb)
local VLb=QLb.coming
if not(VLb and#VLb>0 and QLb.waveSec)then
return true
end
local WLb=QLb.eff or 1
local XLb=QLb.money-SLb
local YLb=(QLb.teamDps or 0)*(QLb.shieldK or 1)+(TLb or 0)*WLb+eb.dpsFor(RLb,math.max(0,XLb))*WLb
local ZLb=(QLb.farmNow or 0)+(ULb or 0)
local _Lb=(QLb.roadSec or 130)*U.clamp(QLb.cover or 0.6,0.1,1)
local aMb=QLb.hpAlive or 0
for bMb,cMb in ipairs(VLb)do
aMb=math.max(0,aMb+cMb.hp-YLb*QLb.waveSec)
local dMb=YLb*_Lb
if aMb>dMb then
return false,bMb,dMb/math.max(1,aMb)
end
if bMb< #VLb then
YLb=YLb+eb.dpsFor(RLb,(cMb.reward or 0)+ZLb)*WLb*(0.85^bMb)
end
end
return true
end
function eb.decide(eMb,fMb)
local gMb=U.clamp(fMb.cover or 0.6,0.1,1)
local hMb=math.max(O.clearSec,0.7*(fMb.roadSec or 50)*gMb)
local iMb=(fMb.clearSec or 0)>hMb
fMb.piling=fMb.piling and iMb
local jMb=fMb.attackers>0 and fMb.pressure<math.min(O.safeReach,gMb*0.75)and not fMb.piling and not iMb
local kMb=fMb.pressure>=math.min(O.dangerReach,gMb*0.9)or(fMb.piling and fMb.enemies>=18)
local lMb,mMb
for nMb,oMb in ipairs(eMb)do
if oMb.farm then
if O.farmUnits and oMb.gain>0 then
oMb.payback=oMb.cost/oMb.gain
if fMb.left-1>=oMb.payback+(fMb.farmSpare or O.farmSpare)and(not lMb or oMb.payback<lMb.payback)then
lMb=oMb
end
end
else
oMb.ratio=oMb.gain/math.max(1,oMb.cost)
if not mMb or oMb.ratio>mMb.ratio then
mMb=oMb
end
end
end
if fMb.leak and fMb.attackers>0 then
local pMb
for qMb,rMb in ipairs(eMb)do
local sMb=not fMb.airLeak or(rMb.e and bb.cardAir(rMb.e.id))
if rMb.place and not rMb.farm and not rMb.idol and not rMb.grif and sMb and rMb.cost<=fMb.money and not(rMb.e and V.allyBuff(rMb.e.id))and(not pMb or rMb.gain>pMb.gain)then
pMb=rMb
end
end
if pMb then
return pMb,string.format(SJe[4058],math.floor(fMb.leak*100))
end
end
local tMb=fMb.future<fMb.wantLeft*1.1
local uMb,vMb,wMb=true,nil,nil
if lMb then
uMb,vMb,wMb=eb.keepsUp(fMb,eMb,lMb.cost,0,lMb.gain)
end
local xMb=fMb.coming and not eb.keepsUp(fMb,eMb,0,0,0)
local yMb=false
if bb.random and lMb and not kMb and fMb.attackers>=2 and lMb.payback<=fMb.left/3 then
local zMb=0
for AMb,BMb in ipairs(bb.mine or{})do
if V.isFarm(BMb._stats.id.Value)then
zMb=zMb+1
end
end
yMb=not lMb.place or zMb<4
end
if xMb and fMb.attackers>0 then
kMb=true
end
if kMb and mMb and mMb.grif then
mMb=nil
for CMb,DMb in ipairs(eMb)do
if not DMb.farm and not DMb.grif and(not mMb or DMb.ratio>mMb.ratio)then
mMb=DMb
end
end
end
local EMb=math.max(1,fMb.incomeRate or 20)
local FMb=fMb.waveSec or 20
local function GMb(HMb,IMb,JMb)
local KMb=math.max(0,(HMb.cost-fMb.money)/EMb)
local LMb=HMb.gain*math.max(0,JMb-KMb)
if IMb then
local MMb=math.max(0,fMb.money-HMb.cost)
local NMb=KMb+math.max(0,(IMb.cost-MMb)/EMb)
LMb=LMb+IMb.gain*math.max(0,JMb-NMb)
end
return LMb
end
local OMb,PMb
if fMb.attackers==0 and mMb then
local QMb=4*FMb
local RMb={}
for SMb,TMb in ipairs(eMb)do
local UMb=type(O.placeFirst)==SJe[2259]and type(TMb.e)==SJe[2259]and table.find(O.placeFirst,TMb.e.id)~=nil
if TMb.place and not TMb.farm and not TMb.grif then
table.insert(RMb,{o=TMb,v=GMb(TMb,nil,QMb)*(UMb and 1e6 or 1),pf=UMb})
end
end
table.sort(RMb,function(VMb,WMb)
