end)
local XMb=fMb.opener and RMb[fMb.opener]and fMb.opener or 1
local YMb=RMb[XMb]and RMb[XMb].o
OMb,PMb=YMb or mMb,XMb>1 and SJe[4059]or((RMb[XMb]and RMb[XMb].pf)and SJe[4060]or SJe[4061])
elseif O.farmFirst and lMb and not kMb and not bb.random then
OMb=lMb
PMb=string.format(SJe[4062],lMb.payback,fMb.left)
elseif lMb and jMb and tMb and not kMb and uMb then
OMb=lMb
PMb=string.format(SJe[4063],lMb.payback,fMb.left,fMb.coming and#fMb.coming or 0)
elseif yMb then
OMb=lMb
PMb=string.format(SJe[4064],lMb.payback,fMb.left)
elseif mMb then
OMb=mMb
if xMb then
PMb=string.format(SJe[4065])
elseif kMb then
PMb=string.format(SJe[4066],math.floor(fMb.pressure*100),math.floor(gMb*100))
elseif lMb and not uMb then
PMb=string.format(SJe[4067],vMb or 1,math.floor((wMb or 0)*100))
elseif lMb and iMb then
PMb=string.format(SJe[4068],math.min(999,math.floor(fMb.clearSec)),math.floor(hMb))
elseif lMb and fMb.piling then
PMb=string.format(SJe[4069],fMb.enemies)
elseif lMb and not jMb then
PMb=SJe[4070]
elseif lMb and not tMb then
PMb=SJe[4071]
else
PMb=SJe[4072]
end
end
if not OMb then
return nil
end
if OMb.cost>fMb.money then
local ZMb
if not OMb.farm then
local _Mb=((fMb.pressure or 0)>=0.95 and 0.5 or kMb and 2 or 6)*FMb
if tonumber(fMb.left)and fMb.left>=0 then
_Mb=math.min(_Mb,(fMb.left+1)*FMb)
end
local aNb
for bNb,cNb in ipairs(eMb)do
if not cNb.farm and cNb~=OMb and cNb.cost<=fMb.money and not(kMb and cNb.grif)then
local dNb=GMb(cNb,OMb,_Mb)
local eNb=GMb(OMb,cNb,_Mb)
if dNb>eNb and(not aNb or dNb>aNb)then
ZMb,aNb=cNb,dNb
end
end
end
end
if not ZMb then
return nil,nil,string.format(SJe[4073],U.fmt(OMb.cost),OMb.what or SJe[2510],math.ceil((OMb.cost-fMb.money)/EMb),math.floor(EMb),PMb),{cost=OMb.cost,what=OMb.what,sec=math.ceil((OMb.cost-fMb.money)/EMb),rate=math.floor(EMb),why=PMb}
end
OMb,PMb=ZMb,PMb..SJe[4074]
end
return OMb,PMb
end
