function gb.objective(rhc)
if rhc.kscore then
return(tonumber(rhc.kills)or 0)+rhc.wave*0.01
end
return(rhc.won and 1000 or 0)+rhc.wave*10-(rhc.won and rhc.t/60 or((rhc.left or 1)*9-math.min(9,rhc.t/60)))
end
gb.LADDER={1,1.3,1.7,2.2,3,4,6,8,12,16,24}
