local vhc
for whc,xhc in ipairs(gb.LADDER)do
vhc=gb.run(shc,thc,{hpMul=xhc,layout=uhc})
if not vhc.won then
return xhc,vhc
end
end
return gb.LADDER[#gb.LADDER],vhc
end
gb.TEAM_FASTER,gb.TEAM_FASTER_S=0.05,15
function gb.teamFaster(yhc,zhc,Ahc)
