if not(Dhc and Dhc.won)then
return nil
end
local Ehc,Fhc=tonumber(Ahc.minutes)*60,tonumber(Chc.t)or math.huge
if Fhc<=Ehc*(1-gb.TEAM_FASTER)and Ehc-Fhc>=gb.TEAM_FASTER_S then
