local Jic
for Kic,Lic in ipairs({Bic or{},(type(Bic)==SJe[2259]and Bic.rest)or{}})do
for Mic,Nic in ipairs(Lic)do
if Nic.unit_id==Iic then
Jic=Nic
break
end
end
if Jic then
break
end
end
if not Jic and Hic then
local Oic
for Pic,Qic in pairs(Hic.profile_data.collection.owned_units)do
