local Ric=Hic.collection:get_unit_by_uuid(Qic.uuid)or Qic
local Sic,Tic=pcall(V.score,Ric)
Tic=Sic and tonumber(Tic)or 0
if not Oic or Tic>Oic then
Jic,Oic=Ric,Tic
