if type(Dpc)==SJe[2259]and Dpc.kind==SJe[2729]and type(P.live.tn)==SJe[2259]and P.live.tn.traitless and F.where~=SJe[2340]then
local Epc=V.noTraits
V.noTraits=true
local Fpc=table.pack(pcall(Cpc,Dpc,...))
V.noTraits=Epc
if not Fpc[1]then
error(Fpc[2],0)
end
return table.unpack(Fpc,2,Fpc.n)
end
return Cpc(Dpc,...)
end
end
jb.T={CURSE=0,SHOP=1,MONEY=2,GOLD=3,CHEST=4,BOSS=5,OPEN=6,SHRINE=7}
jb.TAG_NAMES={[0]=SJe[2455],[1]=SJe[3414],[2]=SJe[4305],[3]=SJe[4306],[4]=SJe[4307],[5]=SJe[4308],[6]=SJe[4309],[7]=SJe[4310]}
jb.KNOWN={_started=true,_items=true,selected_next=true,next=true,_resources=true}
jb.ROOMS=20
function jb.core()
if not jb._core then
jb._core=N.core(SJe[4311])
end
return jb._core
end
function jb.data()
local Gpc=N.prof()
return Gpc and type(Gpc.dungeon_data)==SJe[2259]and Gpc.dungeon_data or nil
end
function jb.item(Hpc)
local Ipc=jb.core()
return Hpc and Ipc and type(Ipc.ITEMS)==SJe[2259]and Ipc.ITEMS[Hpc]or nil
end
function jb.isCurse(Jpc)
return tostring(Jpc):sub(1,7)==SJe[4312]
end
function jb.tags(Kpc)
local Lpc={}
for Mpc,Npc in pairs(type(Kpc)==SJe[2259]and type(Kpc._t)==SJe[2259]and Kpc._t or{})do
if Npc then
Lpc[tonumber(Mpc)or-1]=true
end
end
return Lpc
end
function jb.list(Opc)
local Ppc={}
for Qpc,Rpc in pairs(type(Opc)==SJe[2259]and Opc or{})do
local Spc=tonumber(Qpc)
if Spc and type(Rpc)==SJe[2259]then
table.insert(Ppc,{choice=Spc,key=Qpc,r=Rpc,tags=jb.tags(Rpc),d=tonumber(Rpc._d)or 1})
end
end
table.sort(Ppc,function(Tpc,Upc)
return Tpc.choice<Upc.choice
end)
return Ppc
end
function jb.rooms(Vpc)
return jb.list(Vpc and Vpc.next)
end
function jb.after(Wpc,Xpc)
return jb.list(Wpc and type(Wpc.next)==SJe[2259]and Wpc.next[SJe[4313]..tostring(Xpc)]or nil)
end
function jb.depth(Ypc)
local Zpc=jb.rooms(Ypc)[1]
return Zpc and Zpc.d or nil
end
function jb.items(_pc)
local aqc={}
for bqc,cqc in pairs(_pc and type(_pc._items)==SJe[2259]and _pc._items or{})do
local dqc=type(cqc)==SJe[2259]and cqc.id or(type(cqc)==SJe[1164]and cqc)or nil
if dqc then
aqc[dqc]=(aqc[dqc]or 0)+1
end
end
return aqc
end
function jb.curses(eqc)
local fqc=0
for gqc,hqc in pairs(jb.items(eqc))do
if jb.isCurse(gqc)then
fqc=fqc+hqc
end
end
return fqc
end
function jb.res(iqc)
local jqc=iqc and type(iqc._resources)==SJe[2259]and iqc._resources or{}
return tonumber(jqc.money)or 0,tonumber(jqc.treasure)or 0,tonumber(jqc.treasure_gold)or 0
end
function jb.lives(kqc)
local lqc=tonumber(kqc and kqc.lives)or tonumber(kqc and type(kqc.selected_next)==SJe[2259]and kqc.selected_next.lives)
if lqc then
if lqc~=P.dg.lives then
P.dg.lives=lqc
F.saveSoon()
end
return lqc
end
local mqc=tonumber(P.dg.lives)
return(mqc and mqc>0)and mqc or 5
end
function jb.luck(nqc)
local oqc=jb.core()
local pqc,qqc=pcall(function()
return oqc.calculate_luck_multiplier(nqc)
end)
return pqc and tonumber(qqc)or 1
end
function jb.tagText(rqc)
local sqc={}
for tqc=0,7 do
if rqc[tqc]then
table.insert(sqc,jb.TAG_NAMES[tqc])
end
end
return#sqc>0 and table.concat(sqc,SJe[2911])or SJe[4314]
end
function jb.share(uqc)
local vqc,wqc=0,0
for xqc,yqc in ipairs(V.equipped())do
local zqc=yqc.id or(yqc.u and yqc.u.unit_id)
if zqc and yqc.u and not V.isFarm(zqc)and not V.allyBuff(zqc)then
local Aqc=V.rows(zqc)
local Bqc,Cqc=pcall(V.dps,yqc.u,Aqc and Aqc.max or 0,nil)
Cqc=Bqc and tonumber(Cqc)or 0
local Dqc,Eqc=V.types(zqc)
vqc=vqc+Cqc
if Eqc==uqc or Eqc==uqc..SJe[2478]then
wqc=wqc+Cqc
end
end
end
return vqc>0 and wqc/vqc or 0.5
end
function jb.itemValue(Fqc,Gqc)
local Hqc=jb.item(Fqc)
if not Hqc or jb.isCurse(Fqc)then
return 0
end
local Iqc=0
if tonumber(Hqc.luck_increase)then
Iqc=Iqc+300*Hqc.luck_increase
end
if tonumber(Hqc.star_remnant_chest_add)then
Iqc=Iqc+150*Hqc.star_remnant_chest_add
end
if Fqc==SJe[4315]then
local Jqc,Kqc=jb.res(Gqc)
Iqc=Iqc+60+25*Kqc
end
if Fqc==SJe[4316]then
Iqc=Iqc+120
end
for Lqc,Mqc in pairs(type(Hqc.wave_modifier_effects)==SJe[2259]and Hqc.wave_modifier_effects or{})do
local Nqc=math.abs(tonumber(Mqc.amount)or 0)
if Mqc.type==SJe[4317]and Mqc.stat==SJe[2709]then
Iqc=Iqc+100*Nqc
elseif Mqc.type==SJe[4317]and Mqc.stat==SJe[2710]then
Iqc=Iqc+100*Nqc/math.max(0.2,1-Nqc)
elseif Mqc.type==SJe[4317]and Mqc.stat==SJe[2527]then
Iqc=Iqc+50*Nqc
elseif Mqc.type==SJe[4318]and Mqc.stat==SJe[4319]then
Iqc=Iqc+100*Nqc*jb.share(SJe[2449])
elseif Mqc.type==SJe[4318]and Mqc.stat==SJe[4320]then
Iqc=Iqc+100*Nqc*jb.share(SJe[2447])
elseif Mqc.type==SJe[4318]and Mqc.stat==SJe[4321]then
Iqc=Iqc+100*Nqc*jb.share(SJe[4170])
elseif Mqc.type==SJe[4322]and Mqc.stat==SJe[4323]then
Iqc=Iqc+60*Nqc*jb.share(SJe[2449])
elseif Mqc.type==SJe[4324]then
Iqc=Iqc+40*Nqc
elseif Mqc.type==SJe[4325]then
Iqc=Iqc+80*Nqc
elseif Mqc.type==SJe[4326]then
Iqc=Iqc+80*Nqc
end
end
return Iqc
end
jb.CURSE_COST={_curse_money=0.5,_curse_shop=0.5,_curse_health=0.5,_curse_speed=0.5,_curse_regen=0.5,_curse_shield=1,_curse_explode=1.5,_curse_random=2,_curse_super_health=1,_curse_super_speed=1,_curse_super_regen=1,_curse_super_armored=3,_curse_super_burst=1,_curse_super_explode=3,_curse_super_chaos=3}
function jb.curseCost(Oqc)
if Oqc==SJe[4327]then
local Pqc,Qqc=0,0
for Rqc,Sqc in ipairs(V.equipped())do
local Tqc=Sqc.id or(Sqc.u and Sqc.u.unit_id)
if Tqc and not V.isFarm(Tqc)then
Pqc=Pqc+1
local Uqc,Vqc=pcall(V.airFrom,Tqc)
if Uqc and Vqc then
Qqc=Qqc+(Vqc==0 and 1 or 0.5)
end
end
end
return 1+2*(Pqc>0 and 1-Qqc/Pqc or 0.5)
end
return jb.CURSE_COST[Oqc]or 1.5
end
function jb.roomValue(Wqc,Xqc)
local Yqc,Zqc=Wqc.tags,Wqc.d
local _qc=0
if Yqc[jb.T.GOLD]then
_qc=_qc+12
end
if Yqc[jb.T.CHEST]then
_qc=_qc+4
end
if Yqc[jb.T.MONEY]then
_qc=_qc+(Zqc<=15 and 2 or 0.5)
end
if Yqc[jb.T.SHOP]then
if Zqc>=10 and Zqc<=15 then
_qc=_qc+(Xqc>=300 and 5 or 1)
else
_qc=_qc+(Xqc>=300 and(Zqc>15 and 3 or 1)or 0.3)
end
end
if Yqc[jb.T.SHRINE]then
_qc=_qc+1.5
end
if Yqc[jb.T.CURSE]then
_qc=_qc-jb.curseCost(jb.roomCurse(Wqc.r))
end
return _qc
end
function jb.mod(arc)
local brc={weak={},strong={}}
for crc,drc in pairs(type(arc)==SJe[2259]and type(arc._weak_against)==SJe[2259]and arc._weak_against or{})do
if type(drc)==SJe[2259]and drc.damage_type then
brc.weak[drc.damage_type]=W.weakAmp(drc.amplification)
end
end
for erc,frc in pairs(type(arc)==SJe[2259]and type(arc._strong_against)==SJe[2259]and arc._strong_against or{})do
brc.strong[type(frc)==SJe[2259]and frc.damage_type or frc]=true
end
return(next(brc.weak)or next(brc.strong))and brc or nil
end
function jb.roomCurse(grc)
local hrc=type(grc)==SJe[2259]and type(grc._t)==SJe[2259]and grc._t or{}
local irc=hrc[0]or hrc[SJe[4328]]
return type(irc)==SJe[2259]and irc.id or nil
end
function jb.fx(jrc,krc,lrc)
local mrc={dmg=1,cd=1,range=1,cost=1,hp=1,speed=1,regen=0,crit=0,kinds={},shield=0,fly=0}
local nrc=jb.items(jrc)
if krc and jb.item(krc)then
nrc[krc]=(nrc[krc]or 0)+1
end
if lrc and jb.item(lrc)then
nrc[lrc]=(nrc[lrc]or 0)+1
end
for orc,prc in pairs(nrc)do
local qrc=jb.item(orc)
for rrc,trc in pairs(type(qrc and qrc.wave_modifier_effects)==SJe[2259]and qrc.wave_modifier_effects or{})do
local urc=(tonumber(trc.amount)or 0)*prc
if trc.type==SJe[4317]and trc.stat==SJe[2709]then
mrc.dmg=mrc.dmg+urc
elseif trc.type==SJe[4317]and trc.stat==SJe[2710]then
mrc.cd=mrc.cd+urc
elseif trc.type==SJe[4317]and trc.stat==SJe[2527]then
mrc.range=mrc.range+urc
elseif trc.type==SJe[4318]and tostring(trc.stat):sub(1,9)==SJe[4329]then
local vrc=tostring(trc.stat):sub(10)
mrc.kinds[vrc]=(mrc.kinds[vrc]or 0)+urc
elseif trc.type==SJe[4322]and trc.stat==SJe[4323]then
mrc.crit=mrc.crit+urc
elseif trc.type==SJe[4326]then
mrc.cost=mrc.cost+urc
elseif trc.type==SJe[4330]and trc.stat==SJe[3872]then
mrc.hp=mrc.hp+urc
elseif trc.type==SJe[4325]then
mrc.speed=mrc.speed+urc
elseif trc.type==SJe[4331]then
mrc.regen=mrc.regen+urc
elseif trc.type==SJe[4332]then
mrc.shield=mrc.shield+urc
elseif trc.type==SJe[4333]and trc.passive==SJe[4334]then
mrc.fly=mrc.fly+urc
elseif trc.type==SJe[4333]and trc.passive==SJe[4335]then
mrc.burst=(mrc.burst or 0)+urc
end
end
end
mrc.cd,mrc.cost,mrc.speed=math.max(0.1,mrc.cd),math.max(0.1,mrc.cost),math.max(0.1,mrc.speed)
return mrc
end
function jb.fxText(wrc)
local xrc={}
local function yrc(zrc,Arc)
if math.abs(Arc-1)>0.001 then
table.insert(xrc,string.format(SJe[4194],zrc,Arc))
end
end
yrc(SJe[2709],wrc.dmg)
yrc(SJe[3069],wrc.cd)
yrc(SJe[2527],wrc.range)
yrc(SJe[4336],wrc.cost)
for Brc,Crc in pairs(wrc.kinds)do
table.insert(xrc,string.format(SJe[2798],Brc,math.floor(Crc*100+0.5)))
end
if wrc.crit>0 then
table.insert(xrc,string.format(SJe[4221],math.floor(wrc.crit*100+0.5)))
end
yrc(SJe[4337],wrc.hp)
yrc(SJe[4338],wrc.speed)
if wrc.regen>0 then
table.insert(xrc,string.format(SJe[4339],math.floor(wrc.regen*100+0.5)))
end
if wrc.shield>0 then
table.insert(xrc,string.format(SJe[4340],math.floor(wrc.shield+0.5)))
end
if wrc.fly>0 then
table.insert(xrc,string.format(SJe[4341],math.floor(wrc.fly*100+0.5)))
end
if(wrc.burst or 0)>0 then
table.insert(xrc,string.format(SJe[4342],math.floor(wrc.burst*100+0.5)))
end
return#xrc>0 and table.concat(xrc,SJe[2383])or SJe[2860]
end
function jb.sim(Drc,Erc,Frc)
if not O.sim or type(Drc.r._l)~=SJe[2259]then
return nil
end
local Grc=tostring(Drc.r._r or(Drc.d..SJe[2412]..Drc.choice))..(Erc and(SJe[2589]..tostring(Erc))or SJe[1178])..(Frc and SJe[4343]or SJe[1178])
local Hrc=jb.data()
local Irc=jb.fx(Hrc,jb.roomCurse(Drc.r),Erc)
local Jrc=W.teamSig()..SJe[2272]..jb.fxText(Irc)..(O.killZone~=false and SJe[4344]or SJe[1178])..(bb.forcedWay()and(SJe[2272]..tostring(O.placeMode))or SJe[1178])
local Krc=P.dg.sim[Grc]
if Krc and Krc.sig==Jrc then
return not Krc.none and Krc or nil
end
local Lrc={}
for Mrc,Nrc in ipairs(V.equipped())do
table.insert(Lrc,Nrc.u)
end
if#Lrc==0 then
return nil
end
local Orc=gb.applyFx(gb.info(gb.slim(Drc.r._l),SJe[3020],nil,jb.mod(Drc.r._l)),Irc)
jb.applyK(Orc,Drc.r._r)
if Frc then
Orc.zone=false
end
local Prc=gb.wave(Orc,1,true)
if#Prc==0 then
Krc={none=true,sig=Jrc,at=os.time()}
else
local Qrc=gb.evaluate(Orc,gb.teamFrom(Lrc,Orc.map))
Krc={p=Qrc.p,wave=Qrc.wave,won=Qrc.won,total=Orc.total,margin=Qrc.margin,sig=Jrc,at=os.time(),zone=Orc.zone~=false or nil}
end
P.dg.sim[Grc]=Krc
if U.count(P.dg.sim)>60 then
local Rrc,Src
for Trc,Urc in pairs(P.dg.sim)do
if not Src or(Urc.at or 0)<Src then
Rrc,Src=Trc,Urc.at or 0
end
end
P.dg.sim[Rrc]=nil
end
F.saveSoon()
return not Krc.none and Krc or nil
end
function jb.winP(Vrc)
local Wrc=tostring(math.min(4,math.max(1,math.ceil(Vrc.d/5))))
local Xrc=P.dg.depth[Wrc]or{runs=0,wins=0}
local Yrc=U.clamp(0.95-0.015*Vrc.d,0.5,0.95)
local Zrc=((tonumber(Xrc.wins)or 0)+Yrc*2)/((tonumber(Xrc.runs)or 0)+2)
local _rc,asc=pcall(jb.sim,Vrc)
if _rc and asc and asc.p then
local bsc,csc=pcall(gb.styleP,asc,asc.zone==false and SJe[4184]or(asc.zone and SJe[4118]or nil))
Zrc=(Zrc*2+(bsc and csc or asc.p))/3
end
return Zrc,_rc and asc or nil
end
function jb.hopeless(dsc)
return dsc~=nil and dsc.won==false and(tonumber(dsc.p)or 1)<=0.05
end
function jb.stake(esc)
local fsc,gsc,hsc=jb.res(esc)
return gsc+2*hsc
end
function jb.curseBar(isc,jsc)
local ksc=jb.stake(isc)
if jsc>=15 or ksc>=8 then
return 0.9,SJe[4345],ksc
end
if jsc>=10 or ksc>=4 then
return 0.6,SJe[4346],ksc
end
return 0.1,SJe[4347],ksc
end
function jb.blindCurse(lsc,msc)
return jb.fxText(jb.fx(lsc,msc))==jb.fxText(jb.fx(lsc))
end
function jb.curseOk(nsc,osc,psc,qsc,rsc)
local ssc=tostring((jb.item(nsc)or{}).name or nsc)
local tsc,usc,vsc=jb.curseBar(osc,psc)
if tsc>0.2 and jb.blindCurse(osc,nsc)then
return false,string.format(SJe[4348],ssc,vsc)
end
local function wsc(xsc)
return xsc==nil or(tonumber(xsc.p)or 1)>=tsc
end
if qsc then
local ysc,zsc=pcall(jb.sim,qsc,nil,true)
if ysc and not wsc(zsc)then
return false,string.format(SJe[4349],ssc,(usc:gsub(SJe[3948],SJe[4350])),tostring(zsc.margin or SJe[2510]))
end
end
if#rsc==0 then
return true
end
local Asc
for Bsc,Csc in ipairs(rsc)do
local Dsc,Esc=pcall(jb.sim,Csc,nsc,true)
if not Dsc or wsc(Esc)then
return true
end
if not Asc or(tonumber(Esc.p)or 0)>(tonumber(Asc.p)or 0)then
Asc=Esc
end
end
return false,string.format(SJe[4351],ssc,usc,tostring(Asc and Asc.margin or SJe[2510]))
end
function jb.curseGate(Fsc,Gsc)
local Hsc=jb.roomCurse(Fsc.r)
if not Hsc then
return true
end
return jb.curseOk(Hsc,Gsc,Fsc.d,Fsc,jb.after(Gsc,Fsc.choice))
end
function jb.payValue()
local Isc,Jsc=0,0
for Ksc,Lsc in ipairs(P.dg.pay or{})do
if type(Lsc.items)==SJe[2259]then
local Msc=tonumber(Lsc.gems)or 0
for Nsc,Osc in pairs(Lsc.items)do
if(tonumber(Osc)or 0)>0 then
Msc=Msc+W.itemValue(Nsc,Osc)
end
end
Isc,Jsc=Isc+Msc,Jsc+1
end
end
if Jsc<5 then
return nil
end
return Isc/Jsc*0.7
end
jb.LOSS_PRIOR={won=3,n=12}
function jb.lossWin()
local Psc=type(P.dg)==SJe[2259]and type(P.dg.lossCalls)==SJe[2259]and P.dg.lossCalls or{}
return U.clamp(((tonumber(Psc.won)or 0)+jb.LOSS_PRIOR.won)/((tonumber(Psc.n)or 0)+jb.LOSS_PRIOR.n),0.05,0.95)
end
function jb.pick(Qsc)
local Rsc,Ssc=jb.curses(Qsc),jb.lives(Qsc)
local Tsc=jb.res(Qsc)
local Usc=jb.rooms(Qsc)
local Vsc={}
for Wsc,Xsc in ipairs(Usc)do
table.insert(Vsc,tostring(Xsc.r._r))
end
local Ysc=table.concat(Vsc,SJe[3161])..string.format(SJe[4352],Ssc,Tsc,Rsc,W.teamSig())
if jb._pick and jb._pick.sig==Ysc then
return jb._pick.x
end
local Zsc,_sc,atc,btc
for ctc,dtc in ipairs(Usc)do
local etc=jb.roomValue(dtc,Tsc)
local ftc,gtc
for htc,itc in ipairs(jb.after(Qsc,dtc.choice))do
local jtc=jb.roomValue(itc,Tsc)
if not ftc or jtc>ftc then
ftc,gtc=jtc,itc
end
end
local ktc,ltc=jb.winP(dtc)
local mtc=ltc~=nil and ltc.won==false
local ntc=Ssc>=3 and 1 or(Ssc==2 and 2 or 6)
local otc=1-(1-ktc)^math.max(1,Ssc)
dtc.oldScore=otc*(etc+0.6*(ftc or 0))-(1-ktc)*ntc
if mtc then
ktc=math.min(ktc,jb.lossWin())
otc=ktc
ntc=ntc*2
end
dtc.p,dtc.sim,dtc.value,dtc.nextValue,dtc.nextRoom,dtc.simLost=ktc,ltc,etc,ftc or 0,gtc,mtc or nil
dtc.score=otc*(etc+0.6*(ftc or 0))-(1-ktc)*ntc
local ptc,qtc,rtc=pcall(jb.curseGate,dtc,Qsc)
if ptc and not qtc then
dtc.blocked=rtc
end
if not dtc.blocked then
if not Zsc or dtc.score>Zsc.score then
Zsc=dtc
end
if mtc then
if not btc or dtc.score>btc.score then
btc=dtc
end
elseif not atc or dtc.score>atc.score then
atc=dtc
end
end
if not _sc or dtc.score>_sc.score then
_sc=dtc
end
end
if Zsc and Zsc.simLost and atc then
F.log(1,SJe[4353],string.format(SJe[4354],jb.roomName(Zsc),tostring(Zsc.sim and Zsc.sim.margin or SJe[2510]),math.floor((1-jb.lossWin())*100+0.5),jb.roomName(atc)))
elseif Zsc and btc and btc~=Zsc and btc.oldScore>Zsc.score then
F.log(1,SJe[4353],string.format(SJe[4355],jb.roomName(btc),tostring(btc.sim and btc.sim.margin or SJe[2510]),jb.roomName(Zsc)))
end
Zsc=Zsc or _sc
jb._pick={sig=Ysc,x=Zsc,rooms=Usc}
return Zsc
end
function jb.roomName(stc)
local ttc=type(stc.r._l)==SJe[2259]and stc.r._l or{}
return string.format(SJe[4356],tostring(ttc._location_name or ttc.map or SJe[2510]),jb.tagText(stc.tags))
end
function jb.screens(utc)
local vtc={}
for wtc,xtc in pairs(type(utc.current_shops)==SJe[2259]and utc.current_shops or{})do
if type(xtc)==SJe[2259]then
table.insert(vtc,{i=tonumber(wtc)or 0,t=tonumber(xtc._t),data=xtc.data})
end
end
table.sort(vtc,function(ytc,ztc)
return ytc.i<ztc.i
end)
return vtc
end
function jb.cleared(Atc)
return math.max(1,(jb.depth(Atc)or(jb.ROOMS+1))-1)
end
function jb.state(Btc)
if Btc._dead then
return SJe[3064]
end
local Ctc=jb.screens(Btc)[1]
if Btc._finished and(not Ctc or Ctc.t==jb.T.OPEN)then
