table.insert(TAc,VAc.part.Position)
end
local WAc=0
for XAc=2,#TAc do
WAc=WAc+(TAc[XAc]-TAc[XAc-1]).Magnitude
end
local YAc=0
for ZAc=2,#TAc do
local _Ac,aBc=TAc[ZAc-1],TAc[ZAc]
local bBc=(aBc-_Ac).Magnitude
local cBc=math.max(1,math.floor(bBc/2))
for dBc=0,cBc-1 do
local eBc=_Ac:Lerp(aBc,dBc/cBc)
table.insert(bb.samples,{pos=eBc,prog=(YAc+bBc*dBc/cBc)/math.max(1,WAc),lane=RAc.Name})
end
YAc=YAc+bBc
end
if TAc[#TAc]then
table.insert(bb.samples,{pos=TAc[#TAc],prog=1,lane=RAc.Name})
end
end
end
pcall(bb.readHidden,QAc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
