function bb.readHidden(hBc)
local iBc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(iBc)~=SJe[2259]or not next(iBc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local jBc
for kBc,lBc in pairs(hBc)do
if iBc[kBc.Name]and type(lBc.points)==SJe[2259]and#lBc.points>=2 then
local mBc={}
for nBc,oBc in ipairs(lBc.points)do
mBc[nBc]=U.flat(oBc.part.Position)
end
local pBc={}
for qBc,rBc in ipairs(bb.samples)do
local sBc=tostring(rBc.lane)
pBc[sBc]=pBc[sBc]or{}
table.insert(pBc[sBc],rBc)
end
local tBc,uBc
for vBc,wBc in pairs(pBc)do
local xBc=0
for yBc=1,#mBc,math.max(1,math.floor(#mBc/20))do
local zBc=math.huge
for ABc,BBc in ipairs(wBc)do
local CBc=(U.flat(BBc.pos)-mBc[yBc]).Magnitude
if CBc<zBc then
zBc=CBc
end
end
xBc=xBc+zBc
end
if not uBc or xBc<uBc then
tBc,uBc=vBc,xBc
end
end
local DBc,EBc,FBc,GBc,HBc,IBc={},nil,nil,nil,0,0
for JBc,KBc in ipairs(mBc)do
local LBc,MBc=nil,math.huge
for NBc,OBc in ipairs(pBc[tBc])do
local PBc=(U.flat(OBc.pos)-KBc).Magnitude
if PBc<MBc then
MBc,LBc=PBc,OBc.prog
end
end
IBc=math.max(IBc,MBc)
if FBc then
local QBc=LBc-FBc
local RBc=(QBc>0.002 and 1)or(QBc< -0.002 and-1)or GBc
if GBc and RBc and RBc~=GBc then
table.insert(DBc,math.floor(FBc*1000+0.5)/1000)
end
GBc,HBc=RBc or GBc,HBc+math.abs(QBc)
else
EBc=LBc
end
FBc=LBc
if JBc%50==0 then
task.wait()
end
end
if FBc and IBc<=8 then
table.insert(DBc,math.floor(FBc*1000+0.5)/1000)
jBc=jBc or{}
jBc[kBc.Name]={from=math.floor((EBc or 0)*1000+0.5)/1000,len=math.floor(HBc*1000+0.5)/1000,turns=DBc,road=tBc}
end
end
end
if not jBc then
return
end
local SBc=bb.ld.map
P.maps[SBc]=P.maps[SBc]or{}
local TBc=P.maps[SBc].hidden
P.maps[SBc].hidden=jBc
if type(TBc)~=SJe[2259]then
for UBc,VBc in pairs(jBc)do
F.log(1,SJe[2947],string.format(SJe[4489],UBc,VBc.len,tostring(VBc.road),math.floor((#VBc.turns-1)/2)))
end
F.saveSoon()
end
end
function bb.countLanes()
