for g0c,h0c in ipairs(__c)do
if(U.flat(h0c.pos)-e0c).Magnitude<=f0c then
W_c,X_c=math.min(W_c,h0c.prog),math.max(X_c,h0c.prog)
end
end
end
end
end
if X_c<=W_c then
W_c,X_c=0.75,0.98
end
local i0c=(U_c or Y_c)+1
local j0c=({W_c,X_c,(W_c+X_c)/2,W_c-(X_c-W_c)/2})[i0c]
if not j0c then
