end
local k0c=V.range(T_c.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local l0c={}
for m0c,n0c in ipairs(bb.cands)do
local o0c,p0c,q0c=U.flat(n0c),0,0
for r0c,s0c in ipairs(__c)do
if(U.flat(s0c.pos)-o0c).Magnitude<=k0c then
q0c=q0c+1
if math.abs(s0c.prog-j0c)<=0.05 then
p0c=p0c+1
