for u0c,v0c in ipairs(Z_c)do
if(t0c-v0c.p).Magnitude<=v0c.r then
p0c=p0c-0.5
break
end
end
end
end
end
if p0c>0 then
table.insert(l0c,{pos=n0c,sc=p0c,cov=q0c})
end
if m0c%60==0 then
task.wait()
end
end
table.sort(l0c,function(w0c,x0c)
return w0c.sc>x0c.sc
end)
for y0c,z0c in ipairs(l0c)do
