function bb.learn()
local epd=bb.calRun and bb.calRun.potBy
if type(epd)~=SJe[2259]then
return
end
pcall(bb.sampleHelpers,true)
local fpd={}
for gpd,hpd in pairs(bb.ownDealt or{})do
if not V.isFarm(hpd.id)then
fpd[hpd.id]=(fpd[hpd.id]or 0)+(tonumber(hpd.v)or 0)
end
end
for ipd,jpd in pairs(bb.helperDealt or{})do
if jpd.owner and V.SUMMONER[jpd.owner]and not V.droneHelper(jpd)then
fpd[jpd.owner]=(fpd[jpd.owner]or 0)+(tonumber(jpd.v)or 0)
end
end
local kpd=type(bb.calRun.potExp)==SJe[2259]and bb.calRun.potExp or{}
local lpd,mpd=0,0
local npd={}
for opd,ppd in pairs(epd)do
if ppd>0 then
lpd,mpd=lpd+(fpd[opd]or 0),mpd+ppd
local qpd=tonumber(kpd[opd])or ppd
if qpd>0 then
table.insert(npd,{id=opd,r=(fpd[opd]or 0)/qpd,w=qpd})
end
end
end
if lpd<=0 or mpd<=0 then
return
end
table.sort(npd,function(rpd,spd)
return rpd.r<spd.r
end)
local function tpd(upd)
local vpd,wpd=0,0
for xpd,ypd in ipairs(npd)do
if ypd.id~=upd then
vpd=vpd+ypd.w
end
end
if vpd<=0 then
return nil
end
for zpd,Apd in ipairs(npd)do
if Apd.id~=upd then
wpd=wpd+Apd.w
if wpd>=vpd/2 then
return Apd.r
end
end
end
end
bb.lastEff={}
for Bpd,Cpd in pairs(epd)do
local Dpd=tpd(Bpd)
if Cpd>0 and Cpd/mpd>0.02 and Dpd and Dpd>0 then
local Epd=P.learn[Bpd]or{eff=1,n=0,v=6}
V.learnUp(Bpd,Epd)
local Fpd=math.max(0.02,0.25*math.sqrt(30/(30+Epd.n)))
local Gpd=U.clamp(((fpd[Bpd]or 0)/Cpd)/Dpd,0.2,6)
bb.lastEff[Bpd]=math.floor(Gpd*1000+0.5)/1000
Epd.eff=Epd.eff+(Gpd-Epd.eff)*Fpd
Epd.n=Epd.n+1
P.learn[Bpd]=Epd
end
end
local Hpd=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if Hpd and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==SJe[2259]and P.mapLearn or{}
local Ipd=type(P.mapLearn[Hpd])==SJe[2259]and P.mapLearn[Hpd]or{}
for Jpd,Kpd in pairs(bb.lastEff)do
local Lpd=type(Ipd[Jpd])==SJe[2259]and Ipd[Jpd]or{eff=Kpd,n=0,v=6}
if(tonumber(Lpd.v)or 0)<4 then
Lpd.eff,Lpd.v=(tonumber(Lpd.eff)or Kpd)*V.secRescale(Jpd),4
end
if(tonumber(Lpd.v)or 0)<5 then
Lpd.eff,Lpd.v=(tonumber(Lpd.eff)or Kpd)*(V.sumRescale(Jpd)or 1),5
end
if(tonumber(Lpd.v)or 0)<6 then
Lpd.eff,Lpd.v=(tonumber(Lpd.eff)or Kpd)*(1-(V.SUMMONER[Jpd]and V.SUMMONER[Jpd].droneShare or 0)),6
end
local Mpd=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(Lpd.n)or 0))))
Lpd.eff=(tonumber(Lpd.n)or 0)==0 and Kpd or((tonumber(Lpd.eff)or Kpd)+(Kpd-(tonumber(Lpd.eff)or Kpd))*Mpd)
Lpd.n=(tonumber(Lpd.n)or 0)+1
Ipd[Jpd]=Lpd
end
Ipd._at=os.time()
P.mapLearn[Hpd]=Ipd
if U.count(P.mapLearn)>80 then
local Npd,Opd
for Ppd,Qpd in pairs(P.mapLearn)do
if not Opd or(tonumber(Qpd._at)or 0)<Opd then
Npd,Opd=Ppd,tonumber(Qpd._at)or 0
end
end
P.mapLearn[Npd]=nil
end
end
end
