local Yvd=Vvd.base/Xvd
local Zvd,_vd=0,0
local awd,bwd=Uvd.foes or{},Vvd.foes or{}
for cwd,dwd in pairs(bwd)do
if dwd.prog>=bb.BASE_END then
Zvd=Zvd+dwd.hp
local ewd=awd[cwd]
if ewd then
_vd=_vd+math.max(0,ewd.hp-dwd.hp)
end
end
end
for fwd,gwd in pairs(awd)do
if gwd.prog>=bb.BASE_END and not bwd[fwd]then
