table.insert(yCd,{id=zCd,dps=ACd[1].dps*bb.airBoost(ACd[1].m)*bb.reach(ACd[1].m)})
end
table.sort(yCd,function(DCd,ECd)
return DCd.dps>ECd.dps
end)
for FCd=1,math.min(3,#yCd)do
