end
local GCd
for HCd,ICd in pairs(nCd)do
local JCd=table.clone(ICd)
table.sort(JCd,function(KCd,LCd)
if KCd.lvl~=LCd.lvl then
return KCd.lvl<LCd.lvl
end
return KCd.dps<LCd.dps
end)
for MCd,NCd in ipairs(JCd)do
if NCd.m==bb.freshM and MCd>1 then
table.remove(JCd,MCd)
table.insert(JCd,1,NCd)
break
end
end
local OCd,PCd,QCd,RCd
for SCd,TCd in ipairs(JCd)do
local UCd,VCd=U.flat(TCd.m:GetPivot().Position),TCd.m._stats.range.Value
local WCd,XCd,YCd=0,0,nil
for ZCd,_Cd in ipairs(ICd)do
if _Cd~=TCd and(U.flat(_Cd.m:GetPivot().Position)-UCd).Magnitude<=VCd then
WCd,XCd=WCd+_Cd.dps,XCd+1
if not YCd or _Cd.dps>YCd.dps then
YCd=_Cd
end
end
end
if XCd>0 then
OCd,PCd,QCd,RCd=TCd,WCd,XCd,YCd
break
end
end
RCd=RCd or ICd[1]
local aDd=RCd.dps*bb.airBoost(RCd.m)*bb.reach(RCd.m)*(HCd==bb.planId and 2 or 1)
if(bb.mergeIds[HCd]or HCd==bb.planId)and(OCd or vCd[HCd])and(not GCd or aDd>GCd.score)then
GCd={id=HCd,top=RCd,fresh=OCd,near=PCd or 0,n=QCd or 0,coming=vCd[HCd],score=aDd}
end
end
bb.planId,bb.freshM=GCd and GCd.id,GCd and GCd.fresh and GCd.fresh.m
bb.mergeHeldAt=(kCd and GCd and GCd.fresh)and(bb.mergeHeldAt or bb.wave())or nil
if not GCd then
return F.status(SJe[4981],SJe[5079])
end
local bDd,cDd=bb.wave(),(bb.total or 30)-bb.wave()
local dDd=(bb.pressure or 0)>=math.min(O.dangerReach,((bb.depth and bb.depth.units>0 and bb.depth.covEnd)or 1)*0.9)
local eDd=GCd.fresh
local fDd=not dDd and cDd>3
GCd.waits=eDd and eDd.lvl<=GCd.top.lvl and GCd.top.lvl<GCd.top.max and fDd or false
local gDd=(not eDd or eDd.lvl>=GCd.top.lvl)and GCd.coming and fDd
local hDd=bb.cloneCard and GCd.top.lvl>=GCd.top.max and fDd
local iDd=eDd and eDd.lvl>GCd.top.lvl and GCd.near<0.3*eDd.dps
GCd.ready=kCd and eDd~=nil and not iDd and(not(GCd.waits or gDd or hDd)or bDd-(bb.mergeHeldAt or bDd)>=5)
bb.holdNoCardAt=(GCd.waits and not kCd)and(bb.holdNoCardAt or bDd)or nil
GCd.hold=GCd.waits and(kCd or bDd-(bb.holdNoCardAt or bDd)<4)
bb.mergePlan=GCd
F.status(SJe[4981],eDd and string.format(SJe[5080],V.name(GCd.id),GCd.n,GCd.n==1 and SJe[5081]or SJe[5082],eDd.lvl,GCd.ready and SJe[5083]or(kCd and SJe[5084]or SJe[5085]))or string.format(SJe[5086],V.name(GCd.id)))
end
function bb.mergeHold(jDd)
local kDd=bb.mergePlan
return kDd and kDd.hold and kDd.fresh and kDd.fresh.m==jDd or false
end
function bb.mergeBoost(lDd)
local mDd=bb.mergePlan
