P.fh.noMerge[ADd]=(P.fh.noMerge[ADd]or 0)+1
elseif CDd>0 and BDd>=0.5*CDd then
P.fh.noMerge[ADd]=nil
end
F.log(1,SJe[5002],string.format(SJe[5087],V.name(uDd._stats.id.Value),U.fmt(vDd.own),U.fmt(xDd),vDd.lvl,U.fmt(vDd.near),U.fmt(yDd),vDd.top))
