function bb.idolMeasure()
local eEd
for fEd,gEd in ipairs(bb.mine)do
local hEd=gEd._stats.id.Value
local iEd=gEd._stats:FindFirstChild(SJe[2709])
if not V.isFarm(hEd)and not V.idol(hEd)and iEd and iEd.Value>0 then
eEd=gEd
