local lEd,mEd=pcall(N.USC.calculate_upgrade_cost_multiplier,eEd,N.session())
local nEd=jEd:FindFirstChild(SJe[4827])and tonumber(jEd.buff_damage_multiplier.Value)or 0
return jEd.damage.Value*(1+nEd),lEd and tonumber(mEd)or nil
