end
if rEd==oEd and sEd==pEd then
return F.log(2,SJe[4793],SJe[5089])
end
local tEd=P.fh.idol or{n=0,dmg=0,cost=0}
tEd.n,tEd.dmg,tEd.cost=tEd.n+1,tEd.dmg+(rEd/oEd-1),tEd.cost+(1-sEd/pEd)
P.fh.idol=tEd
F.log(1,SJe[4793],string.format(SJe[5090],V.name(jEd.id.Value),(rEd/oEd-1)*100,(1-sEd/pEd)*100))
end)
