function bb.trainCount()
local qFd=P.train.on
if not(qFd and bb.trainee)then
return
end
local rFd=0
for sFd,tFd in ipairs(bb.mine)do
local uFd=tFd._stats
local vFd=uFd:FindFirstChild(SJe[2651])and uFd.uuid.Value
local wFd=vFd==bb.trainee and uFd:FindFirstChild(qFd.what==SJe[2930]and SJe[5110]or SJe[2664])
if wFd then
rFd=rFd+(tonumber(wFd.Value)or 0)
end
end
bb.trainTk=math.max(bb.trainTk or 0,rFd)
F.status(SJe[3569],string.format(SJe[5111],V.name(qFd.id),bb.trainTk,qFd.what,U.fmt(qFd.have+(qFd.got or 0)+bb.trainTk),U.fmt(qFd.need)))
