function bb.trainDone(xFd,yFd)
local zFd=P.train.on
if not(zFd and bb.trainee)then
return
end
bb.trainCount()
local AFd=bb.trainTk or 0
zFd.got=(zFd.got or 0)+AFd
local BFd=P.trainSim[xFd]and tonumber(P.trainSim[xFd].tk)
if not bb.joinedMid then
local CFd=P.train.real[xFd]or{n=0,sum=0}
CFd.n,CFd.sum=CFd.n+1,CFd.sum+AFd
P.train.real[xFd]=CFd
if BFd and BFd>0 then
local DFd=P.train.cal
DFd.real,DFd.sim,DFd.n=(DFd.real or 0)+AFd,(DFd.sim or 0)+BFd,(DFd.n or 0)+1
end
end
table.insert(P.train.log,1,{key=xFd,got=AFd,won=yFd,at=os.time()})
while#P.train.log>20 do
table.remove(P.train.log)
end
F.log(1,SJe[3562],string.format(SJe[5112],V.name(zFd.id),AFd,zFd.what,yFd and SJe[3045]or SJe[3046],BFd and string.format(SJe[5113],BFd)or SJe[1178],U.fmt(ib.realHave(zFd)),U.fmt(zFd.need)))
if not yFd then
P.train.bad[xFd]=os.time()+3600
F.log(1,SJe[3562],SJe[5114])
end
end
