bb.SKIP_LOOK={every=2,upTo=20}
function bb.skipSafe()
if bb.noBuy or bb.trialId or bb.stopping or bb.finished then
return false,SJe[5115]
end
local GFd,HFd=bb.wave(),tonumber(bb.total)or 0
if HFd>0 and GFd>=HFd and not bb.infinite then
return false,SJe[5116]
end
if#(bb.mine or{})==0 then
return false,SJe[5117]
end
if bb.depth and bb.depth.leak then
return false,SJe[5118]
end
for IFd,JFd in ipairs(bb.enemies or{})do
if JFd.boss then
return false,SJe[5119]
end
end
local KFd=(bb.depth and(bb.depth.units or 0)>0 and tonumber(bb.depth.covEnd))or 1
local LFd=tonumber(bb.pressure)or 0
local MFd=math.min(O.safeReach or 0.45,KFd*0.75)
if LFd>=MFd then
return false,string.format(SJe[5120],math.floor(LFd*100+0.5))
end
return true,string.format(SJe[5121],math.floor(LFd*100+0.5),math.floor(KFd*100+0.5))
end
function bb.skipVote()
if O.skipVote==false or not O.master or not O.battle or P.pauseAll or bb.skipBusy then
return
end
local NFd,OFd=pcall(function()
return M._settings.autoskip_waves.Value
end)
if NFd and OFd==true then
return
end
bb.skipBusy=true
local PFd,QFd=bb.wave(),U.now()
local RFd
while F.alive and bb.skipOpen and not bb.finished and bb.wave()==PFd and U.now()-QFd<bb.SKIP_LOOK.upTo do
local SFd,TFd=bb.skipSafe()
RFd=TFd
if SFd then
local UFd=F.request(SJe[5122],SJe[3988])
if UFd then
bb.skipVotes=(bb.skipVotes or 0)+1
if bb.skipVotes==1 then
F.log(1,SJe[2947],string.format(SJe[5123],PFd,tostring(TFd)))
end
end
RFd=nil
break
end
task.wait(bb.SKIP_LOOK.every)
end
if RFd and not bb.skipSaid then
bb.skipSaid=true
F.log(2,SJe[2947],string.format(SJe[5124],PFd,RFd))
end
bb.skipBusy=false
end
bb.TO_LOBBY_WAIT=30
function bb.toLobby(VFd)
F.req.back.lobby=nil
local WFd,XFd=F.request(SJe[2339],SJe[3985])
if not(bb.leavingAt and U.now()-bb.leavingAt<60)then
bb.leavingAt=U.now()
task.spawn(function()
local YFd=U.now()
while F.alive and U.now()-YFd<bb.TO_LOBBY_WAIT do
if ab.teleportingNow()then
return
end
task.wait(0.5)
end
if not F.alive or ab.teleportingNow()then
return
end
F.log(1,SJe[2947],string.format(SJe[5125],tostring(VFd or SJe[5126]),bb.TO_LOBBY_WAIT,WFd and SJe[5127]or tostring(XFd)))
ab.toLobbyPlace(VFd or SJe[5126])
end)
end
return WFd,XFd
end
bb.NEW_ROUND_HOLD=4
function bb.newRound()
if bb.rematchReady then
return SJe[5128]
end
local ZFd=workspace:FindFirstChild(SJe[5129])
local _Fd=ZFd and ZFd:FindFirstChild(SJe[5130])
local aGd=_Fd~=nil and _Fd.Value==false
if aGd then
bb.roundDownAt=bb.roundDownAt or U.now()
else
bb.roundDownAt=nil
end
if bb.rematchStarted then
return U.now()-bb.rematchStarted>=60 and SJe[5131]or nil
end
if aGd and U.now()-bb.roundDownAt>=bb.NEW_ROUND_HOLD then
return SJe[5132]
end
return nil
