function bb.modPair(sKd,tKd)
if tKd<=0.02 or tKd>=1.2 then
return
end
local uKd=P.enemyMods[sKd]or{r={}}
P.enemyMods[sKd]=uKd
table.insert(uKd.r,tKd)
while#uKd.r>80 do
table.remove(uKd.r,1)
end
local vKd=gb.modRead(uKd)
local wKd=uKd.said and vKd and math.abs(vKd-uKd.said)<=uKd.said*0.1
if vKd and not wKd then
uKd.said=vKd
end
local xKd,yKd=sKd==SJe[4123]and SJe[5236]or(sKd==SJe[2818]and SJe[5237]or SJe[4124]),sKd==SJe[4123]and SJe[5238]or(sKd==SJe[4122]and SJe[5239]or SJe[5240])
if vKd and not wKd then
F.log(1,SJe[2947],string.format(SJe[5241],xKd,#uKd.r,vKd,yKd))
end
if vKd==false and not uKd.saidLoose then
uKd.saidLoose=true
local zKd=table.clone(uKd.r)
table.sort(zKd)
F.log(1,SJe[2947],string.format(SJe[5242],xKd,#zKd,zKd[1],zKd[#zKd]))
end
end
